'use strict';
(function(){
 const $=s=>document.querySelector(s);
 const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 if(!$('#respond-context')||!$('#summary-report')){const fresh=new URL(window.location.href);fresh.searchParams.set('release','plain-english');window.location.replace(fresh.href);return}
 const gbp=x=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:2}).format(x);
 const pct=(a,b)=>b?(100*a/b).toFixed(1)+'%':'Not sampled';
 const names=['Choose a case','Move the information','Match the information','Check the records','Explore the dashboard','Review & finish'];
 const labels={CaseReference:'Case reference',ProductCategory:'Product or programme',CaseStatus:'Open or closed',ComplaintCategory:'Complaint type',ComplaintPathway:'Complaint pathway',EvidenceCompleteness:'Evidence completeness',SpecialistReview:'Specialist review',ReportedSafetyConcern:'Reported safety concern',RootCauseTheme:'Complaint theme',DateReceived:'Date received',SupportRequired:'Additional support needed',WorkflowStage:'Current complaint stage',Decision:'Complaint outcome',RecordedAwardGBP:'Recorded award',ReviewTeam:'Review team',QualityResult:'Complaint-handling QA result',MigrationCohort:'Migration group',LinkedThemes:'Linked complaint themes'};
 const checks={CaseReference:'Keep the reference so a figure can be traced back to its case.',ProductCategory:'Use the agreed product or programme name.',CaseStatus:'Report open and closed cases separately.',ComplaintCategory:'Keep the specific reason for the complaint.',ComplaintPathway:'Keep commission complaints separate from vehicle-quality complaints.',EvidenceCompleteness:'Keep missing evidence visible; this does not automatically fail the data check.',SpecialistReview:'Show whether a specialist still needs to review the case.',ReportedSafetyConcern:'Flag a reported concern for review; this does not confirm a fault.',RootCauseTheme:'Group related complaints without claiming a proven cause.',DateReceived:'Check it is a real date, no later than the reporting date.',SupportRequired:'Use an explicit Yes or No so support needs are not lost.',WorkflowStage:'Show where the complaint is in its journey.',Decision:'Keep the recorded outcome separate from whether the record passed data checks.',RecordedAwardGBP:'Check the amount is valid. A recorded award is not proof of payment.',ReviewTeam:'Use an agreed team name.',QualityResult:'Keep investigation QA separate from data-quality checks.',MigrationCohort:'Keep the group used for programme comparisons.',LinkedThemes:'Keep the related themes used in the 3D view.'};
 let fullData,data,pool=[],scope='all',step=0,selected=0,mode='extract',includeExceptions=true,result=null,ack=false,runCount=0;
 const chosen=()=>pool[selected],source=()=>RespondDemo.sourceRecord(chosen()),batch=()=>RespondDemo.fixture(pool,includeExceptions);
 const dashboardHref=(harm=false)=>'index.html?scope='+encodeURIComponent(scope)+(harm?'&cause='+encodeURIComponent(chosen().root_cause)+'#harm':'#programme-explorer');
 const title=(n,heading,copy)=>`<div class="eyebrow">STEP ${n} / ${names[n-1].toUpperCase()}</div><h3>${heading}</h3><p>${copy}</p>`;
 const technical=body=>`<details class="technical-details"><summary>Show technical details</summary>${body}</details>`;
 const field=(label,value)=>`<div><small>${esc(label)}</small><strong>${esc(value)}</strong></div>`;
 const display=(key,value)=>key==='RecordedAwardGBP'?gbp(value):['SupportRequired','ReportedSafetyConcern'].includes(key)?(value==='Y'?'Yes':'No'):Array.isArray(value)?value.join(', '):String(value??'');
 function readinessCards(cases){
  const totals=CaseReadiness.counts(cases);
  return `<div class="progress-counts"><div><strong>${totals.waiting}</strong><span>Open — waiting for evidence or review</span></div><div><strong>${totals.ready}</strong><span>Open — ready for the next action</span></div><div><strong>${totals.closed}</strong><span>Closed cases</span></div></div><p class="plain-note">These are complaint-progress categories, separate from passing the data checks. They add up to the ${cases.length} records that passed. “Ready” uses example checks for the current stage, not an approval to act.</p>`;
 }
 function rules(){return '<p>Example next-action rules: closed cases stay closed. Intake cases can be ready for triage even if investigation evidence is still needed later. Other stages require complete evidence. Investigation and later stages also require any specialist review to be completed. Decision and later stages cannot have an unresolved QA failure. Redress and final-letter stages need a recorded decision. A reported safety concern needs completed specialist review. A person still authorises the next action. These rules do not change any case.</p>'}
 function render(){
  $('#integration-steps').innerHTML=names.map((name,i)=>`<button data-step="${i}" ${i>3&&!result?'disabled':''} ${i===step?'aria-current="step"':''}><span>0${i+1}</span>${name}</button>`).join('');
  document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{step=Number(b.dataset.step);render()});
  $('#integration-back').disabled=step===0;$('#step-progress').textContent=`Step ${step+1} of 6`;
  $('#integration-next').disabled=step===3&&!result;
  $('#integration-next').textContent=step===5?'Finish and open the dashboard →':step===4?'Continue to human review →':'Next step →';
  const c=chosen(),s=source(),r=result;
  let html='';
  if(step===0){
   const profile=fullData.programmes.find(p=>p.product===c.product),progress=CaseReadiness.assess(c);
   html=title(1,'Start with a complaint record.','Choose a fictional case to follow. This is an example of the information we would take from a case-management system such as Respond. It is not an Aptean screen or an official field layout.');
   html+=`<div class="pick-case"><label for="source-case">Follow a sample case</label><select id="source-case">${pool.map((x,i)=>`<option value="${i}" ${i===selected?'selected':''}>${esc(x.case_id)} · ${esc(x.product)} · ${esc(x.complaint_type)}</option>`).join('')}</select></div><div class="content-grid"><div class="source-card"><div class="source-heading"><strong>Example complaint record</strong><span>FICTIONAL DATA</span></div><div class="source-fields">${field('Case reference',c.case_id)}${field('Open or closed',c.status)}${field('Product / programme',c.product)}${field('Complaint type',c.complaint_type)}${field('Current stage',c.stage)}${field('Evidence completeness',c.evidence_status)}${field('Specialist review',c.specialist_review)}${field('Recorded award — not necessarily paid',gbp(c.redress))}</div><div class="context-evidence"><b>${esc(progress.status)}</b><p>${esc(progress.reason)}</p></div></div><aside class="control-card"><h4>What stays in Respond?</h4><p>The investigation, evidence, decisions and customer communications remain in the case system. The dashboard helps people see the overall picture.</p><h4>Evidence relevant to this case area</h4><ul>${profile.evidence.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>${esc(profile.control)}</p></aside></div>`;
  }else if(step===1){
   html=title(2,'How would complaint data reach the dashboard?','Think of Respond as a filing cabinet and the dashboard as a noticeboard. We need a safe way to copy the right information from one to the other.');
   html+=`<div class="simple-journey"><span>Complaint records in Respond</span><b>→</b><span>Approved information transfer</span><b>→</b><span>Checks, then dashboard reporting</span></div><div class="transfer-options"><label><input type="radio" name="transfer" value="extract" ${mode==='extract'?'checked':''}><span><b>Checked spreadsheet export</b><small>An approved file is exported, checked and used to update the dashboard. The agreed process could run on a schedule.</small></span></label><label><input type="radio" name="transfer" value="api" ${mode==='api'?'checked':''}><span><b>Secure automatic connection (API)</b><small>Supporting software would ask Respond for approved information automatically, through an interface agreed with the platform owner and Aptean.</small></span></label></div><div class="plain-callout"><b>Simulated example — no live Respond connection.</b><p>Both choices use the same made-up records. Switching the option changes the explanation; it does not connect to Respond.</p></div>`;
   html+=technical(`<div class="content-grid"><pre>${esc(JSON.stringify({demo_only:true,transfer:mode==='extract'?'governed_file_extract':'supported_api_adapter_design_only',schema_version:'fictional-contract-v2',snapshot:data.as_of,records:batch().length,context:scope,respond_network_request:false},null,2))}</pre><div class="control-card"><h4>Security and delivery controls to agree</h4><p>Approved access, minimum necessary fields, encrypted transfer, protected server-side credentials, supported interface, completeness checks, bounded retries, monitoring and controlled reprocessing. These production controls are not provisioned by this demo.</p></div></div>`);
  }else if(step===2){
   const canonical=RespondDemo.canonical(s);
   html=title(3,'How Respond information becomes dashboard data.','We match each piece of information to the right place in the dashboard. The case reference stays attached, so people can trace a reported figure back to its records.');
   html+=`<div class="table-scroll"><table class="mapping-table friendly-mapping"><thead><tr><th>Information from the case system</th><th>Used in the dashboard as</th><th>What we check</th></tr></thead><tbody>${RespondDemo.mappings.map(([from])=>`<tr><td><b>${esc(labels[from]||from)}</b><small>${esc(display(from,s[from]))}</small></td><td>${esc(labels[from]||from)}<small>${esc(display(from,s[from]))}</small></td><td>${esc(checks[from]||'Use the agreed meaning and format.')}</td></tr>`).join('')}</tbody></table></div>`;
   html+=technical(`<p>These field names are independently designed examples, not an official Respond schema. A business analyst would agree the real meanings with operations, data owners and the Respond configuration team.</p><div class="table-scroll"><table class="mapping-table"><thead><tr><th>Example source field</th><th>Analytical field</th><th>Mapping rule</th></tr></thead><tbody>${RespondDemo.mappings.map(([from,to,note])=>`<tr><td>${from}<small>${esc(display(from,s[from]))}</small></td><td>${to}<small>${esc(canonical[to])}</small></td><td>${esc(note)}</td></tr>`).join('')}</tbody></table></div>`);
  }else if(step===3){
   html=title(4,'Check complaint records before they reach the dashboard.','We check for missing information, duplicate cases and incorrect amounts so the dashboard’s figures can be trusted. These checks do not decide whether a complaint is fully investigated or ready to close.');
   html+=`<div class="batch-actions"><label><input id="include-exceptions" type="checkbox" ${includeExceptions?'checked':''}> Include three example mistakes</label><button id="run-validation">${r?'Check the records again':'Check these records'} →</button></div>`;
   if(r){
    html+=`<div class="batch-totals"><div><strong>${r.input}</strong><span>Records checked</span></div><div><strong>${r.totals.accepted}</strong><span>Ready to use in reporting</span></div><div><strong>${r.totals.rejected}</strong><span>Needs correcting</span></div><div><strong>${r.reconciled?'Yes':'No'}</strong><span>All records accounted for?</span></div></div><div class="batch-result">${r.totals.accepted} records passed the data checks. ${r.totals.rejected?r.totals.rejected+' records are set aside for correction and are excluded from the next step.':'No records need correction in this example.'}</div>`;
    if(r.rejected.length)html+=`<h4 class="exception-title">Records that need correcting</h4><div class="table-scroll"><table class="exception-table"><thead><tr><th>Record</th><th>Case reference</th><th>What needs correcting</th></tr></thead><tbody>${r.rejected.map(x=>`<tr><td>${x.row}</td><td>${esc(x.reference==='(missing)'?'No reference provided':x.reference)}</td><td>${x.errors.map(e=>esc(e.includes('Duplicate')?'This case reference appears twice.':e.includes('Missing or invalid source')?'A valid case reference is needed.':e.includes('non-negative')?'The recorded amount cannot be negative.':e.includes('conflicts')?'The recorded amount does not match the complaint outcome.':e)).join('<br>')}</td></tr>`).join('')}</tbody></table></div>`;
   }else html+='<div class="control-card"><h4>What are we checking?</h4><ul><li>A valid case reference, with no duplicate in this group.</li><li>A real received date, no later than the reporting date.</li><li>Recognised products, complaint categories and case stages.</li><li>Amounts and other values in the expected format.</li></ul></div>';
   html+='<p class="plain-note"><b>Missing evidence is different from a missing case reference.</b> A record can pass these checks while saying its investigation evidence is incomplete. The dashboard needs to show that outstanding work.</p>';
   html+=technical('<p>Checks also validate support indicators, complaint/pathway consistency, open/closed state, QA values and linked themes. Duplicate detection is within this batch only. This static demo has no persistent correction queue, cross-batch deduplication or source-system updates.</p>');
  }else if(step===4){
   const cause=data.causes.find(x=>x.name===c.root_cause);
   html=title(5,'See how checked records feed the dashboard.','These figures use the sample records that passed the data checks. They can include both open and closed complaints. Passing a data check does not mean the case has been resolved.');
   html+=`<div class="batch-totals"><div><strong>${r.totals.accepted}</strong><span>Records that passed the data checks</span></div><div><strong>${gbp(r.totals.redress)}</strong><span>Recorded awards — not necessarily paid</span></div><div><strong>${r.totals.sampled}</strong><span>Cases with complaint-handling QA results</span></div><div><strong>${r.totals.failed}</strong><span>Cases that failed complaint-handling QA</span></div></div>${readinessCards(r.accepted)}<div class="network-invitation"><div><div class="eyebrow">EXPLORE THE BIGGER PICTURE</div><h3>Explore customer harm in 3D.</h3><p>See how this complaint theme connects with other issues, case volumes and recorded redress. Rotate the view, select a theme and inspect the supporting cases.</p><span>Selected theme: <b>${esc(c.root_cause)}</b> · ${esc(scope==='all'?'All products and programmes':scope.replace('::',' · '))}</span><a id="explore-3d" href="${dashboardHref(true)}">Explore customer harm in 3D →</a><small>This opens the complaint theme in the main dashboard, not an individual case as a 3D node. The dashboard uses the wider selected population, not just these 12 sample records.</small></div><div class="network-mini" aria-hidden="true"><i></i><i></i><i></i><i></i><b>CUSTOMER<br>HARM</b></div></div><div class="plain-callout"><b>Two journeys, shown separately</b><p>This walkthrough follows the information: records → checks → reporting. Complaint handling follows its own journey: intake → investigation → decision → closure. Select “Continue to human review” to finish this walkthrough.</p></div>`;
   html+=technical(`${rules()}<div class="lineage"><div><small>SOURCE CASE REFERENCE</small><b>${esc(c.case_id)}</b></div><div><small>SELECTED COMPLAINT THEME</small><b>${esc(c.root_cause)}</b></div><div><small>WIDER SELECTED POPULATION — PYTHON / SQLITE</small><b>${cause.volume.toLocaleString('en-GB')} cases · ${gbp(cause.redress)} recorded awards</b></div></div><p>The 12-case demonstration is separate from the full 10,000-case dataset and does not change it. QA failure rate is ${pct(r.totals.failed,r.totals.sampled)}, using sampled cases only. Theme connections show co-occurrence, not proof of causation.</p>`);
  }else{
   html=title(6,'Review the results before taking action.','You have reached the end of the walkthrough. A person reviews the findings before any real operational action. Downloading a summary is optional—you can finish and explore the dashboard now.');
   html+=`<div class="content-grid"><div><div class="source-card"><h3>Your example results</h3><p>${r.totals.accepted} of ${r.input} records passed the data checks. ${r.totals.rejected} need correction. Of the ${r.totals.sampled} cases with complaint-handling QA results, ${r.totals.failed} failed QA.</p><p class="plain-note">Possible next action: review the records needing correction and any outstanding evidence or specialist reviews. These are prompts for a person, not automated case decisions.</p></div><label class="review-ack"><input id="respond-ack" type="checkbox" ${ack?'checked':''}><span>I have reviewed the example results and outstanding work.<small>Demonstration acknowledgement only. This does not approve a case, payment or real integration.</small></span></label><p id="respond-review-status" class="plain-note">${ack?'Acknowledged in this browser session only.':'Optional: acknowledge that you have reviewed the example.'}</p><div class="finish-actions"><button id="view-summary" class="primary-small">View readable summary report</button><a class="finish-dashboard" href="${dashboardHref()}">Finish and open the dashboard →</a></div><p class="plain-note">The report can be printed or saved as PDF. Neither download nor acknowledgement is required to open the dashboard.</p></div><aside class="control-card"><h4>What happens in a real programme?</h4><p>An authorised person would check the evidence, approve the appropriate action and record it in the case system under the firm’s controls.</p><h4>What happens in this demonstration?</h4><p>You can explore the dashboard and save a summary. No Respond record, customer outcome, payment or complaint assignment is changed.</p></aside></div>`;
   html+=technical('<p>JSON is a structured copy for developers or software tools. It is not required to use the demo. It includes the sample source record, field mapping, data-check results and local acknowledgement. No production approval or persistent audit is created.</p><button id="download-receipt">Download technical data (JSON) ↓</button>');
  }
  $('#integration-content').innerHTML=html;
  if(step===0)$('#source-case').onchange=e=>{selected=Number(e.target.value);ack=false;render()};
  if(step===1)document.querySelectorAll('[name=transfer]').forEach(i=>i.onchange=e=>{mode=e.target.value;ack=false;render()});
  if(step===3){$('#include-exceptions').onchange=e=>{includeExceptions=e.target.checked;result=null;ack=false;render()};$('#run-validation').onclick=()=>{result=RespondDemo.validateBatch(batch(),data.as_of,fullData.programmes);runCount++;ack=false;render()}}
  if(step===5){$('#respond-ack').onchange=e=>{ack=e.target.checked;$('#respond-review-status').textContent=ack?'Acknowledged in this browser session only.':'Optional: acknowledge that you have reviewed the example.'};$('#view-summary').onclick=showSummary;$('#download-receipt').onclick=downloadReceipt}
 }
 function pack(){return {title:'Simulated Aptean Respond integration evidence',demo_only:true,not_vendor_api_specification:true,prepared_at:new Date().toISOString(),snapshot:data.as_of,source_reference:chosen().case_id,transfer_design:mode,selected_context:scope,network_request_to_respond:false,fictional_source_record:source(),canonical_record:RespondDemo.canonical(source()),field_mapping:RespondDemo.mappings,batch:{input:result.input,...result.totals,reconciled:result.reconciled,rejected_records:result.rejected,complaint_progress:CaseReadiness.counts(result.accepted)},local_reviewer_acknowledged:ack,source_system_write_back:false,limits:['Synthetic data only','No live Respond connection','No persistent audit or correction queue','In-batch duplicate checks only','No customer outcome or payment approval','Example next-action rules only','Full programme snapshot unchanged']}}
 function downloadReceipt(){const url=URL.createObjectURL(new Blob([JSON.stringify(pack(),null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='respond-integration-evidence-demo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 function showSummary(){
  const p=pack(),progress=CaseReadiness.counts(result.accepted);
  $('#summary-content').innerHTML=`<div class="eyebrow">GURJIT KAILA / PORTFOLIO DEMONSTRATION</div><h2>Complaint data review summary</h2><p class="report-disclosure">Synthetic data · simulated Respond connection · no real cases changed</p><dl><dt>Product or programme</dt><dd>${esc(scope==='all'?'All products and programmes':scope.replace('::',' · '))}</dd><dt>Reporting snapshot</dt><dd>${esc(data.as_of)}</dd><dt>Prepared</dt><dd>${esc(new Date(p.prepared_at).toLocaleString('en-GB'))}</dd><dt>Transfer example</dt><dd>${mode==='extract'?'Checked spreadsheet export':'Secure automatic connection (API)—design example only'}</dd><dt>Selected case / theme</dt><dd>${esc(chosen().case_id)} / ${esc(chosen().root_cause)}</dd></dl><h3>1. Record checks</h3><p>${result.input} records checked. ${result.totals.accepted} passed and ${result.totals.rejected} need correction. ${result.reconciled?'All records are accounted for.':'The counts do not reconcile.'}</p>${result.rejected.length?'<ul>'+result.rejected.map(x=>`<li>Record ${x.row} (${esc(x.reference)}): ${x.errors.map(esc).join('; ')}.</li>`).join('')+'</ul>':''}<h3>2. Complaint progress for records that passed</h3><ul><li>${progress.waiting} open—waiting for evidence or review.</li><li>${progress.ready} open—ready for the next action under example rules.</li><li>${progress.closed} recorded as closed.</li></ul><p>Passing a data check does not mean a complaint is ready to progress or closed. Example next-action rules are explained below.</p><h3>3. Recorded amounts and investigation QA</h3><p>Recorded awards: ${gbp(result.totals.redress)}. These are not confirmed payments. ${result.totals.sampled} cases have complaint-handling QA results; ${result.totals.failed} failed (${pct(result.totals.failed,result.totals.sampled)}). This QA is separate from record-format and duplicate checks.</p><h3>4. Human review and proposed follow-up</h3><p>Review records needing correction and cases with outstanding evidence, specialist assessments or QA follow-up before deciding any real action.</p><p>Local demonstration acknowledgement: ${ack?'recorded in this browser session':'not given'}. No real approval or source-system update is created.</p><h3>5. How the example progress categories work</h3>${rules()}<h3>6. Scope and limitations</h3><p>This summary covers the 12-case demonstration and any deliberate error records. The main dashboard uses a separate, wider selected population within 10,000 fictional cases. There is no live Aptean Respond connection, automated case decision, payment approval or persistent audit trail.</p><p><a href="${dashboardHref(true)}">Explore this complaint theme in the 3D dashboard</a></p>`;
  $('#summary-report').showModal();
 }
 $('#close-summary').onclick=()=>$('#summary-report').close();$('#print-summary').onclick=()=>window.print();
 $('#integration-back').onclick=()=>{if(step){step--;render()}};
 $('#integration-next').onclick=()=>{if(step===5){window.location.href=dashboardHref();return}if(step<5&&(step!==3||result)){step++;render()}};
 function selectContext(key){
  scope=key;const subset=fullData.cases.filter(c=>ProgrammeExplorer.matches(c,key));data=key==='all'?fullData:fullData.views[key];
  let representatives=[];const seenTypes=new Set();
  if(key==='all')fullData.programmes.forEach(p=>{const examples=subset.filter(c=>c.product===p.product);representatives.push(examples[0]);representatives.push(p.product==='Motor Finance'?examples.find(c=>c.pathway!==examples[0].pathway):examples.find(c=>c.complaint_type!==examples[0].complaint_type)||examples[1])});
  else subset.forEach(c=>{if(!seenTypes.has(c.complaint_type)){representatives.push(c);seenTypes.add(c.complaint_type)}});
  const seen=new Set();pool=[...representatives,...subset].filter(c=>c&&!seen.has(c.case_id)&&seen.add(c.case_id)).slice(0,12);
  selected=0;step=0;result=null;ack=false;runCount=0;
  const profile=ProgrammeExplorer.profile(fullData,key);
  $('#respond-context-description').textContent=(profile?profile.summary+' '+profile.control:'Choose an area to follow relevant sample complaints through the demonstration.')+' Changing area restarts the example and clears the review acknowledgement.';
  $('#integration-status').textContent='Ready · '+(key==='all'?'all six areas':key.replace('::',' · '))+' · 12 fictional cases · no live Respond connection';
  const url=new URL(window.location.href);if(key==='all')url.searchParams.delete('scope');else url.searchParams.set('scope',key);window.history.replaceState({},'',url);render();
 }
 fetch('analytics.json?v=plain-english').then(r=>{if(!r.ok)throw Error('Data unavailable');return r.json()}).then(d=>{fullData=d;const requested=new URLSearchParams(window.location.search).get('scope')||'all';const initial=requested==='all'||d.views[requested]?requested:'all';const picker=$('#respond-context');picker.innerHTML=ProgrammeExplorer.options(d.programmes,initial);picker.value=initial;picker.disabled=false;picker.onchange=()=>selectContext(picker.value);selectContext(initial)}).catch(error=>{console.error("Walkthrough could not load",error);$('#integration-status').textContent='The example data could not load. Please reload the page.';$('#integration-next').disabled=true});
})();


